#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <assert.h>
struct filerec{char *filename;int fd;unsigned int fd_refs;};
static int filerec_fd_mutex;
#define g_mutex_lock(x) ((void)0)
#define g_mutex_unlock(x) ((void)0)
#define abort_on(x) assert(!(x))
#define eprintf(...) fprintf(stderr,__VA_ARGS__)
int filerec_open(struct filerec *file, bool quiet)
{
	int ret = 0;
	int fd;

	g_mutex_lock(&filerec_fd_mutex);
	if (file->fd_refs == 0) {
		abort_on(file->fd != -1);

		fd = open(file->filename, O_RDONLY);
		if (fd == -1) {
			ret = errno;
			if (ret != ENOENT || !quiet)
				eprintf("Error %d: %s while opening \"%s\"\n",
					ret, strerror(ret), file->filename);
			goto out_unlock;
		}

		file->fd = fd;
	}
	file->fd_refs++;
out_unlock:
	g_mutex_unlock(&filerec_fd_mutex);

	return ret;
}
int main(int argc,char **argv){struct filerec f={argv[1],-1,0};int ret=filerec_open(&f,true);struct stat st={0};if(!ret)fstat(f.fd,&st);char c=0;if(!ret)read(f.fd,&c,1);printf("return=%d fd_refs=%u opened_inode=%llu first_byte=%c\n",ret,f.fd_refs,(unsigned long long)st.st_ino,c);if(f.fd>=0)close(f.fd);return ret;}
